{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "The closest retrieved analogue, dicaffeoylquinic acid (Morgan 0.82), showed extremely low mouse brain uptake (0.003% of injected dose at 10 min) and was explicitly characterized as poor brain uptake; this direct in vivo measurement strongly transfers to the caffeoylquinic acid scaffold of the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Ferulic acid, a much smaller phenolic acid fragment, was detected in rat brain and CSF after systemic administration, showing that simple phenolic acids can access the CNS; however, its lower molecular size and polarity limit transfer to the larger, more polar quinic acid ester query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C05"],
      "claim": "Salvianolic acid A was detected in rat brain homogenate and reported to cross the BBB, but this is a larger polyphenolic acid and detection alone does not establish meaningful CNS exposure; it provides only weak contradictory evidence for the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a polar, ionizable caffeoylquinic acid. The closest analogue (dicaffeoylquinic acid, Morgan 0.82) showed negligible mouse brain uptake (0.003% ID), directly supporting poor CNS access. Smaller phenolic acids and some polyphenolic acids can be detected in brain, but their lower size/polarity or detection-only data do not establish meaningful exposure for this scaffold. Overall, the evidence points to inadequate BBB penetration.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule.",
    "Dicaffeoylquinic acid is the closest analogue but has an additional caffeoyl group; the quantitative effect of this difference on brain uptake is unknown.",
    "Potential contribution of active uptake/efflux or peripheral metabolism to brain exposure is not captured.",
    "Route of administration and dose for the query are not specified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

